                                  '    func testVenueCallbacksRetireAcrossDraftAndSessionChanges() throws {\n'
                                  '        for action in ["reload", "leave", "discard", "replace", '
                                  '"draftABA", "account", "epoch", "role", "logout", "sessionABA"] {\n'
                                  '            var seed = TemplateAuthoringDraft(title: "Venue"); '
                                  'seed.usageLocation = "Historical"\n'
                                  '            let (model, owner, _) = try setup(seed)\n'
                                  '            let editor = TemplateAuthoringVenueEditor(model: model)\n'
                                  '            switch action {\n'
                                  '            case "reload": model.load()\n'
                                  '            case "leave": model.leave()\n'
                                  '            case "discard": model.discard()\n'
                                  '            case "replace": model.draft.description = "Other draft '
                                  'bytes"\n'
                                  '            case "draftABA": model.draft.usageLocation = "Other"; '
                                  'model.changed(); model.draft = seed; model.changed()\n'
                                  '            case "account": owner.value = try session(902)\n'
                                  '            case "epoch": owner.value = try session(epoch: 2)\n'
                                  '            case "role": owner.value = try session(role: "merchant")\n'
                                  '            case "sessionABA": owner.value = try session(902); '
                                  'model.load(); owner.value = try session(); model.load()\n'
                                  '            default: owner.value = nil\n'
                                  '            }\n'
                                  '            let after = model.draft\n'
                                  '            XCTAssertFalse(editor.canRead, action); '
                                  'XCTAssertNil(editor.savedRawValue, action)\n'
                                  '            XCTAssertFalse(editor.select(.museum), action); '
                                  'XCTAssertEqual(model.draft, after, action)\n'
                                  '        }\n'
                                  '    }\n'
                                  '    func '
                                  'testVenueStaleCanonicalEquivalentBytesAreRejectedBeforeParentChangeCallback() '
                                  'throws {\n'
                                  '        var seed = TemplateAuthoringDraft(title: "Venue"); '
                                  'seed.usageLocation = "Cafe\\u{301}"\n'
                                  '        let (model, _, _) = try setup(seed), editor = '
                                  'TemplateAuthoringVenueEditor(model: model)\n'
                                  '        model.draft.usageLocation = "Caf\\u{e9}"\n'
                                  '        XCTAssertEqual(model.draft, seed) // Swift String equality is '
