                                  '        XCTAssertFalse(MerchantRegistrationEditEligibility.allows(status: '
                                  '2, auditStatus: 0))\n'
                                  '        let fixtureState = try snapshot(.registration(id: 22), '
                                  'MerchantContentFixtureData.registration)\n'
                                  '        let fixtureDraft = MerchantRegistrationContentDraft(detail: '
                                  'fixture)\n'
                                  '        XCTAssertNoThrow(try '
                                  'MerchantContentCommand.updateRegistration(id: 22, topicID: 70, draft: '
                                  'fixtureDraft).validate(against: fixtureState))\n'
                                  '        for status in -1...4 {\n'
                                  '            for audit in -1...3 {\n'
                                  '                let expected = (status == 0 && audit == 0) || ((status == '
                                  '2 || status == 3) && audit == 2)\n'
                                  '                '
                                  'XCTAssertEqual(MerchantRegistrationEditEligibility.allows(status: status, '
                                  'auditStatus: audit), expected)\n'
                                  '                let raw = '
                                  '"{\\"id\\":22,\\"topicId\\":70,\\"status\\":\\(status),\\"auditStatus\\":\\(audit)}"\n'
                                  '                let state = try snapshot(.registration(id: 22), raw)\n'
                                  '                let draft = MerchantRegistrationContentDraft(detail: try '
                                  'value(MerchantContentFixtureData.registration))\n'
                                  '                let command = '
                                  'MerchantContentCommand.updateRegistration(id: 22, topicID: 70, draft: '
                                  'draft)\n'
                                  '                if expected { XCTAssertNoThrow(try '
                                  'command.validate(against: state)) }\n'
                                  '                else { XCTAssertThrowsError(try command.validate(against: '
                                  'state)) }\n'
                                  '            }\n'
                                  '        }\n'
                                  '    }\n'
                                  '    func testRegistrationEditMissingStateCannotGrantAccess() throws {\n'
                                  '        XCTAssertFalse(MerchantRegistrationEditEligibility.allows(status: '
