                                  "current bytes')\n"
                                  '        registration = _club_registration()\n'
                                  '        raw_contract = (root / CONTRACT_PATH).read_bytes()\n'
                                  '        # Full actual-current admission must happen before '
                                  'projection/cache reads.\n'
                                  '        registration.checked_current(raw_contract, root)\n'
                                  '        restored = {} if collect else None\n'
                                  '        for relative in _CLUB_E2B_SHA256:\n'
                                  '            path = root / relative\n'
                                  '            if path.is_symlink() or path.resolve() != path:\n'
                                  "                raise ValueError('Symlinked finite current club input: ' "
