                                  'simplified, so clip by polyline length rather than sample count.\\npublic '
                                  'enum RoamShareRoutePrivacy {\\n    public static let endpointFraction = '
                                  '0.1\\n\\n    public static func clippedTrack(_ track: [RoamHistoryPoint]) '
                                  '-> [RoamHistoryPoint] {\\n        guard track.count >= 2 else { return [] '
                                  '}\\n        var lengths: [Double] = []\\n        for index in '
                                  '1..<track.count {\\n            let a = track[index - 1], b = '
                                  'track[index]\\n            // A schematic cannot safely interpolate a '
                                  'longitude wrap. Hide it rather than\\n            // drawing a '
                                  'trans-world segment or returning the original endpoints.\\n            '
                                  'guard abs(b.lng - a.lng) <= 180 else { return [] }\\n            '
                                  'lengths.append(RoamExperienceMath.distanceMeters(a.coordinate, '
                                  'b.coordinate))\\n        }\\n        let total = lengths.reduce(0, '
                                  '+)\\n        guard total.isFinite, total > 0 else { return [] }\\n        '
                                  'let start = total * endpointFraction, end = total - start\\n        var '
                                  'travelled = 0.0\\n        var result: [RoamHistoryPoint] = []\\n        '
                                  'for index in 1..<track.count {\\n            let length = lengths[index - '
                                  '1], next = travelled + length\\n            if length > 0, next > start, '
                                  'travelled < end {\\n                let a = track[index - 1], b = '
                                  'track[index]\\n                func interpolate(_ distance: Double) -> '
