  '\n'
  '    def __getattr__(self, name):\n'
  "        require(name in {'is_dir', 'is_file', 'is_symlink', 'resolve', 'exists', 'stat'},\n"
  "                'Unsupported historical path operation: ' + name)\n"
  '        return getattr(self.root / self.relative, name)\n'
  '\n'
